namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Room { get; set; } = string.Empty;
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    IReadOnlyList<Course> GetAllCourses();
    IReadOnlyList<Course> GetFeaturedCourses();
    IReadOnlyList<Course> SearchCourses(string? department, string? search);
    Course? GetCourseById(int id);
    Instructor? GetInstructorById(int id);
    IReadOnlyList<Course> GetCoursesByDepartment(string departmentCode);
    bool SubmitEnrollment(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Code = "MATH", Name = "Mathematics", Description = "Exploration of abstract structures, patterns, and quantitative reasoning." },
            new() { Code = "ENG", Name = "English", Description = "Analysis of literature, writing, and critical communication." },
            new() { Code = "BIO", Name = "Biology", Description = "Study of living organisms and their interactions with the environment." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers in top-tier conferences and holds three patents in natural language processing.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Computer Science", Bio = "Dr. Martinez focuses on distributed systems and cloud computing. He spent ten years in industry at major tech companies before joining academia.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor of Mathematics", Bio = "Dr. Johnson is a leading researcher in combinatorics and graph theory. She has authored two widely adopted textbooks used across universities nationwide.", Email = "sjohnson@university.edu" },
            new() { Id = 4, Name = "Dr. James Liu", Title = "Associate Professor of Mathematics", Bio = "Dr. Liu specializes in applied mathematics and numerical analysis. His research bridges mathematics and engineering applications.", Email = "jliu@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Parker", Title = "Professor of English", Bio = "Dr. Parker is an award-winning author and literary critic specializing in modern American literature. She has received multiple teaching excellence awards.", Email = "eparker@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Torres", Title = "Associate Professor of English", Bio = "Dr. Torres focuses on creative writing and rhetoric. He is a published poet and editor of the University Literary Review.", Email = "mtorres@university.edu" },
            new() { Id = 7, Name = "Dr. Karen Williams", Title = "Professor of Biology", Bio = "Dr. Williams is a renowned molecular biologist whose research on gene expression has been featured in leading scientific journals.", Email = "kwilliams@university.edu" },
            new() { Id = 8, Name = "Dr. David Patel", Title = "Associate Professor of Biology", Bio = "Dr. Patel specializes in ecology and conservation biology. He leads the university's field research station and biodiversity lab.", Email = "dpatel@university.edu" }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Computer Science", DepartmentCode = "CS", CourseNumber = "CS 101", Description = "A foundational course covering programming fundamentals, data types, control structures, and problem-solving techniques using Python. Ideal for students with no prior programming experience.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", DepartmentCode = "CS", CourseNumber = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and hash tables. Algorithm design and analysis with emphasis on time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Room = "Science Hall 305", InstructorId = 1 },
            new() { Id = 3, Title = "Database Systems", DepartmentCode = "CS", CourseNumber = "CS 310", Description = "Introduction to relational database design, SQL, normalization, transaction processing, and modern NoSQL approaches. Includes a semester-long project building a full database application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Tech Building 110", InstructorId = 2 },
            new() { Id = 4, Title = "Artificial Intelligence", DepartmentCode = "CS", CourseNumber = "CS 420", Description = "Exploration of AI concepts including search algorithms, knowledge representation, machine learning, neural networks, and natural language processing.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Tech Building 215", InstructorId = 1, IsFeatured = true },

            // Mathematics
            new() { Id = 5, Title = "Calculus I", DepartmentCode = "MATH", CourseNumber = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and natural sciences. Emphasis on both computational skills and conceptual understanding.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Building 101", InstructorId = 3, IsFeatured = true },
            new() { Id = 6, Title = "Linear Algebra", DepartmentCode = "MATH", CourseNumber = "MATH 220", Description = "Vectors, matrices, linear transformations, eigenvalues, and eigenvectors. Applications to computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Math Building 203", InstructorId = 3 },
            new() { Id = 7, Title = "Probability and Statistics", DepartmentCode = "MATH", CourseNumber = "MATH 301", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference. Real-world data analysis using R.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Room = "Math Building 105", InstructorId = 4 },
            new() { Id = 8, Title = "Discrete Mathematics", DepartmentCode = "MATH", CourseNumber = "MATH 250", Description = "Logic, set theory, combinatorics, graph theory, and number theory. Essential mathematical foundations for computer science and engineering students.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Math Building 301", InstructorId = 4 },

            // English
            new() { Id = 9, Title = "English Composition", DepartmentCode = "ENG", CourseNumber = "ENG 101", Description = "Develop effective writing skills through essay composition, argumentation, and research writing. Focus on clarity, structure, and critical thinking in written communication.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Humanities 110", InstructorId = 5 },
            new() { Id = 10, Title = "American Literature", DepartmentCode = "ENG", CourseNumber = "ENG 220", Description = "Survey of major works in American literature from the colonial period to the present. Examines themes of identity, democracy, and the American experience through fiction, poetry, and drama.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Humanities 205", InstructorId = 5, IsFeatured = true },
            new() { Id = 11, Title = "Creative Writing Workshop", DepartmentCode = "ENG", CourseNumber = "ENG 310", Description = "Hands-on workshop in fiction and poetry writing. Students develop original works, participate in peer critique sessions, and study published authors' craft techniques.", Credits = 3, Schedule = "Wed 2:00–4:50 PM", Room = "Humanities 308", InstructorId = 6 },

            // Biology
            new() { Id = 12, Title = "General Biology I", DepartmentCode = "BIO", CourseNumber = "BIO 101", Description = "Introduction to cell biology, genetics, evolution, and ecology. Includes weekly laboratory sessions with hands-on experiments and microscopy.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", Room = "Life Sciences 100", InstructorId = 7 },
            new() { Id = 13, Title = "Molecular Biology", DepartmentCode = "BIO", CourseNumber = "BIO 301", Description = "DNA replication, transcription, translation, gene regulation, and modern molecular techniques including PCR, gel electrophoresis, and CRISPR.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Room = "Life Sciences 210", InstructorId = 7, IsFeatured = true },
            new() { Id = 14, Title = "Ecology and Conservation", DepartmentCode = "BIO", CourseNumber = "BIO 350", Description = "Study of ecological principles, population dynamics, community ecology, and conservation strategies. Includes field trips to local ecosystems and a conservation project.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", Room = "Life Sciences 115", InstructorId = 8 },
            new() { Id = 15, Title = "Human Anatomy and Physiology", DepartmentCode = "BIO", CourseNumber = "BIO 210", Description = "Comprehensive study of human body systems including skeletal, muscular, nervous, and cardiovascular systems. Laboratory sessions include cadaver study and physiological experiments.", Credits = 4, Schedule = "Tue/Thu 1:00–2:50 PM", Room = "Life Sciences 120", InstructorId = 8 }
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public IReadOnlyList<Course> GetAllCourses() => _courses.AsReadOnly();

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public IReadOnlyList<Course> SearchCourses(string? department, string? search)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(department))
            query = query.Where(c => c.DepartmentCode.Equals(department, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList().AsReadOnly();
    }

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructorById(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(string departmentCode) =>
        _courses.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase)).ToList().AsReadOnly();

    public bool SubmitEnrollment(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return GetCourseById(request.CourseId) != null;
    }
}

