            new() { Id = 6, Title = "Linear Algebra", DepartmentCode = "MATH", CourseNumber = "MATH 220", Description = "Vectors, matrices, linear transformations, eigenvalues, and eigenvectors. Applications to computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Math Building 203", InstructorId = 3 },
            new() { Id = 7, Title = "Probability and Statistics", DepartmentCode = "MATH", CourseNumber = "MATH 301", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference. Real-world data analysis using R.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Room = "Math Building 105", InstructorId = 4 },
            new() { Id = 8, Title = "Discrete Mathematics", DepartmentCode = "MATH", CourseNumber = "MATH 250", Description = "Logic, set theory, combinatorics, graph theory, and number theory. Essential mathematical foundations for computer science and engineering students.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Math Building 301", InstructorId = 4 },

            // English
            new() { Id = 9, Title = "English Composition", DepartmentCode = "ENG", CourseNumber = "ENG 101", Description = "Develop effective writing skills through essay composition, argumentation, and research writing. Focus on clarity, structure, and critical thinking in written communication.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Humanities 110", InstructorId = 5 },
            new() { Id = 10, Title = "American Literature", DepartmentCode = "ENG", CourseNumber = "ENG 220", Description = "Survey of major works in American literature from the colonial period to the present. Examines themes of identity, democracy, and the American experience through fiction, poetry, and drama.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Humanities 205", InstructorId = 5, IsFeatured = true },
            new() { Id = 11, Title = "Creative Writing Workshop", DepartmentCode = "ENG", CourseNumber = "ENG 310", Description = "Hands-on workshop in fiction and poetry writing. Students develop original works, participate in peer critique sessions, and study published authors' craft techniques.", Credits = 3, Schedule = "Wed 2:00–4:50 PM", Room = "Humanities 308", InstructorId = 6 },

            // Biology
            new() { Id = 12, Title = "General Biology I", DepartmentCode = "BIO", CourseNumber = "BIO 101", Description = "Introduction to cell biology, genetics, evolution, and ecology. Includes weekly laboratory sessions with hands-on experiments and microscopy.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", Room = "Life Sciences 100", InstructorId = 7 },
            new() { Id = 13, Title = "Molecular Biology", DepartmentCode = "BIO", CourseNumber = "BIO 301", Description = "DNA replication, transcription, translation, gene regulation, and modern molecular techniques including PCR, gel electrophoresis, and CRISPR.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Room = "Life Sciences 210", InstructorId = 7, IsFeatured = true },
            new() { Id = 14, Title = "Ecology and Conservation", DepartmentCode = "BIO", CourseNumber = "BIO 350", Description = "Study of ecological principles, population dynamics, community ecology, and conservation strategies. Includes field trips to local ecosystems and a conservation project.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", Room = "Life Sciences 115", InstructorId = 8 },
            new() { Id = 15, Title = "Human Anatomy and Physiology", DepartmentCode = "BIO", CourseNumber = "BIO 210", Description = "Comprehensive study of human body systems including skeletal, muscular, nervous, and cardiovascular systems. Laboratory sessions include cadaver study and physiological experiments.", Credits = 4, Schedule = "Tue/Thu 1:00–2:50 PM", Room = "Life Sciences 120", InstructorId = 8 }
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public IReadOnlyList<Course> GetAllCourses() => _courses.AsReadOnly();

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public IReadOnlyList<Course> SearchCourses(string? department, string? search)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(department))
            query = query.Where(c => c.DepartmentCode.Equals(department, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList().AsReadOnly();
    }

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructorById(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(string departmentCode) =>
        _courses.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase)).ToList().AsReadOnly();

    public bool SubmitEnrollment(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return GetCourseById(request.CourseId) != null;
    }
}

