@page "/"
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section text-center text-white py-5 mb-4">
    <div class="container">
        <h1 class="display-4 fw-bold">University Course Catalog</h1>
        <p class="lead">Explore our diverse academic offerings across departments. Find the courses that shape your future.</p>
        <a href="/courses" class="btn btn-gold btn-lg mt-2">Browse All Courses</a>
    </div>
</div>

<h2 class="mb-3">Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-5">
    @foreach (var course in featuredCourses)
    {
        var dept = departments.FirstOrDefault(d => d.Code == course.DepartmentCode);
        <div class="col">
            <div class="card course-card h-100 shadow-sm">
                <div class="card-body">
                    <span class="badge bg-navy mb-2">@course.CourseNumber</span>
                    <h5 class="card-title">@course.Title</h5>
                    <p class="card-text text-muted">@course.Description[..Math.Min(120, course.Description.Length)]…</p>
                    <p class="mb-1"><strong>Credits:</strong> @course.Credits &nbsp; <strong>Dept:</strong> @dept?.Name</p>
                </div>
                <div class="card-footer bg-transparent border-0 d-flex justify-content-between">
                    <a href="/courses/@course.Id" class="btn btn-outline-navy btn-sm">View Details</a>
                    <a href="/enroll?courseId=@course.Id" class="btn btn-gold btn-sm">Enroll</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mb-3">Departments</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4 mb-4">
    @foreach (var dept in departments)
    {
        <div class="col">
            <div class="card dept-card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h5 class="card-title fw-bold">@dept.Name</h5>
                    <p class="card-text text-muted">@dept.Description</p>
                    <a href="/courses?department=@dept.Code" class="btn btn-outline-navy btn-sm">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private IReadOnlyList<Course> featuredCourses = [];
    private IReadOnlyList<Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@inject ICatalogService CatalogService

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Browse Courses</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-4">
        <label for="department" class="form-label">Department</label>
        <select name="department" id="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
