 <PageTitle>Enroll — University Course Catalog</PageTitle>

 <h1 class="mb-4">Course Enrollment Request</h1>

 @if (submitted)
 {
     <div class="alert alert-success">
         <h4 class="alert-heading">Enrollment Request Submitted!</h4>
         <p>Thank you, <strong>@Model!.StudentName</strong>. Your enrollment request for
             <strong>@(CatalogService.GetCourseById(Model!.CourseId)?.Title ?? "the selected course")</strong>
             has been received.</p>
         <hr />
         <p class="mb-0">Student ID: @Model!.StudentId — You will receive a confirmation via your university email.</p>
     </div>
     <a href="/courses" class="btn btn-outline-navy">Browse More Courses</a>
 }
 else
 {
     <div class="row">
         <div class="col-lg-7">
             <div class="card shadow-sm">
                 <div class="card-body">
                     <EditForm Model="Model" method="post" FormName="EnrollForm" OnValidSubmit="HandleSubmit">
                         <DataAnnotationsValidator />
                         <ValidationSummary class="text-danger mb-3" />

                         <div class="mb-3">
                             <label for="studentName" class="form-label">Full Name</label>
                             <InputText id="studentName" class="form-control" @bind-Value="Model!.StudentName" />
                             <ValidationMessage For="() => Model!.StudentName" />
                         </div>

                         <div class="mb-3">
                             <label for="studentId" class="form-label">Student ID</label>
                             <InputText id="studentId" class="form-control" @bind-Value="Model!.StudentId" />
                             <ValidationMessage For="() => Model!.StudentId" />
                         </div>

                         <div class="mb-3">
                             <label for="courseId" class="form-label">Course</label>
                             <InputSelect id="courseId" class="form-select" @bind-Value="Model!.CourseId">
                                 <option value="0">— Select a course —</option>
                                 @foreach (var course in allCourses)
                                 {
                                     <option value="@course.Id">@course.CourseNumber — @course.Title</option>
                                 }
                             </InputSelect>
                             <ValidationMessage For="() => Model!.CourseId" />
                         </div>

                         <button type="submit" class="btn btn-navy">Submit Enrollment Request</button>
                     </EditForm>
                 </div>
             </div>
         </div>
     </div>
 }

 @code {
     [SupplyParameterFromQuery] public int? CourseId { get; set; }

     [SupplyParameterFromForm]
     public EnrollmentRequest? Model { get; set; }

     protected override void OnParametersSet()
     {
         Model ??= new();
     }

     private IReadOnlyList<Course> allCourses = [];
     private bool submitted;

     protected override void OnInitialized()
     {
         allCourses = CatalogService.GetAllCourses();
         if (CourseId.HasValue && Model!.CourseId == 0)
             Model!.CourseId = CourseId.Value;
     }

     private void HandleSubmit()
     {
         CatalogService.SubmitEnrollment(Model!);
         submitted = true;
     }
 }

